test('P11',async t=>{
 for(const state of ['sealed-preaccept','known-charged-failure','unknown-usage'] as const)await t.test('native-equivalent-failover/'+state,async()=>{
  const a=await n.task(),j=journey(n,{schedule:{usage:state==='unknown-usage'?'never':'manual',outcome:state==='known-charged-failure'?'known-failure':'answer'},...(state==='sealed-preaccept'?{beforeAccept:async(r:EncodedRequest)=>{await n.f.adapterClient().sealUnaccepted(r.original,2);}}:{})});const result=await j.turn(a);assert.equal(result.status,'waiting');const r=j.requests[0]!;
  if(state==='unknown-usage'){const before=await fb.counters();await noDispatch(n,async()=>{await assert.rejects(j.session.switchProfile(a.scope,{...await n.command(a.sessionId),choice:{...AUTO_CHOICE,pin:b.profileId,allowEquivalentFallback:true}}),code('UNKNOWN_EFFECT_REQUIRES_RECONCILIATION'));await assert.rejects(j.session.retryTurn(a.scope,{...await n.command(a.sessionId),operationId:r.original.operationId,input:'controlled answer',choice:{...AUTO_CHOICE,pin:b.profileId,allowEquivalentFallback:true}}),code('UNKNOWN_EFFECT_REQUIRES_RECONCILIATION'));});assert.deepEqual(await fb.counters(),before);assert.ok(result.view.costs.reserved>0);return;}
  await j.models.reconcile(a.scope,r.original);const evidence=await new OwnerFailureVerifier(n.f.adapterClient(),n.f.ownerId,n.profile.profileDigest).resolve(r.original),selection=dual().selectEquivalent({previous:n.profile,evidence,need:n.need,pins:n.pins,now:now(),choice:{...AUTO_CHOICE,pin:b.profileId,allowEquivalentFallback:true}});assert.equal(selection.status,'selected');
  await n.f.admin.query('UPDATE fabric.model_policies SET profile_digests=$3::jsonb WHERE tenant_id=$1 AND space_id=$2',[n.f.tenant,n.f.space,JSON.stringify([n.profile.profileDigest,b.profileDigest])]);
  const next=journey(n,{profiles:dual(),extra:[secondOwner()]}),retried=await next.session.retryTurn(a.scope,{...await n.command(a.sessionId),operationId:r.original.operationId,input:'controlled answer',choice:{...AUTO_CHOICE,pin:b.profileId,allowEquivalentFallback:true}});assert.equal(retried.status,'completed');
  const requests=await requestsFor(n,a.binding.runId);assert.equal(requests.length,2);const second=requests[1]!;assert.equal(second.original.operationId,r.original.operationId);assert.notEqual(second.original.attemptId,r.original.attemptId);assert.notEqual(second.original.reservationId,r.original.reservationId);assert.deepEqual(captured(second).profile,b);const row=await fb.journal(second.original);assert.equal(row.status,'settled');assert.equal(row.request.profileDigest,b.profileDigest);
  const op=(await n.f.admin.query('SELECT record FROM fabric.model_operations WHERE operation_id=$1',[r.original.operationId])).rows[0].record;assert.equal(op.attemptsTaken,2);assert.equal(op.retryCeiling,3);assert.equal(op.status,'settled');assert.equal(retried.view.costs.actual,row.receipt.measuredUnits+(state==='known-charged-failure'?(await n.f.journal(r.original)).receipt.measuredUnits:0));assert.equal(retried.view.pendingModel,null);
 });
 for(const change of ['region','dataPolicy','modelVersion','instructionPackDigest','missing-permission','stale-qualification','unapproved-route'] as const)await t.test('failover-ineligible/'+change,async()=>{
  const a=await n.task(),j=journey(n,{schedule:{outcome:'known-failure'}});await j.turn(a);const r=j.requests[0]!,verifier=new OwnerFailureVerifier(n.f.adapterClient(),n.f.ownerId,n.profile.profileDigest),evidence=await verifier.resolve(r.original);let routing=dual(),choice={...AUTO_CHOICE,allowEquivalentFallback:true},target=b;
  if(change==='missing-permission')choice={...choice,allowEquivalentFallback:false};else if(change==='unapproved-route')routing=dual({rules:{routes:[n.profile.route]}});else if(change==='stale-qualification')routing=dual({qualification:{...qb,revoked:true}});else{target=make({[change]:change==='instructionPackDigest'?sha(80):'changed-semantics'});routing=dual({candidate:target});}
  const before=await fb.counters();await noDispatch(n,async()=>{if(change==='missing-permission')assert.throws(()=>routing.selectEquivalent({previous:n.profile,evidence,need:n.need,pins:n.pins,now:now(),choice:{...choice,pin:target.profileId}}),code('UNAUTHORIZED'));else assert.equal(routing.selectEquivalent({previous:n.profile,evidence,need:n.need,pins:n.pins,now:now(),choice:{...choice,pin:target.profileId}}).status,'waiting');
   const next=journey(n,{profiles:routing,extra:[secondOwner()]}),command={...await n.command(a.sessionId),operationId:r.original.operationId,input:'controlled answer',choice:{...choice,pin:target.profileId}};
   if(change==='missing-permission')await assert.rejects(next.session.retryTurn(a.scope,command),code('UNAUTHORIZED'));else assert.equal((await next.session.retryTurn(a.scope,command)).status,'waiting');
  });assert.deepEqual(await fb.counters(),before);assert.equal((await requestsFor(n,a.binding.runId)).length,1);
 });
});

test('P12',async t=>{
 for(const [label,offset,expected] of [['just-before',-1,'selected'],['exact',0,'waiting'],['after',1,'waiting']] as const)await t.test('qualification-expiry/'+label,async()=>{const at=new Date(Date.parse(n.qualification.expiresAt)+offset).toISOString(),a=await n.task(),j=journey(n),session=new NativeSession(n.native.repository,j.models,{...j.session.ports,profiles:{select:input=>n.profiles.select({...input,now:at})}});const before=await n.f.counters(),result=await session.requestTurn(a.scope,{...await n.command(a.sessionId),input:'expiry boundary',choice:null});assert.equal(result.status,expected==='selected'?'completed':'waiting');if(expected==='waiting'){assert.equal(result.view.wait?.reason,'model-unavailable');assert.deepEqual(await n.f.counters(),before);}else await proveReceipt(n,j.requests[0]!);});
 const variants=()=>({profileVersion:2,profileDigest:sha(11),capabilitiesDigest:sha(12),adapterVersion:'untested',deployment:'changed-deployment',environmentDigest:sha(13),dependencyLockDigest:sha(14),checkDefinitionDigest:sha(15),probeId:randomUUID(),executedCases:['self-declared-unexecuted'],revoked:true});
 for(const [key,value] of Object.entries(variants()))await t.test('qualification-binding/'+key,async()=>{const a=await n.task(),q=LocalQualificationSchema.parse({...n.qualification,[key]:value}),j=journey(n,{profiles:inventory(n,{qualification:q})});await noDispatch(n,async()=>{const result=await j.turn(a);assert.equal(result.view.wait?.reason,'model-unavailable');assert.equal(j.requests.length,0);});});
 await t.test('missing-or-empty-executed-probes-refuse',()=>{assert.throws(()=>LocalQualificationSchema.parse({...n.qualification,executedCases:[]}),code('INVALID_SCHEMA'));const copy={...n.qualification};Reflect.deleteProperty(copy,'executedCases');assert.throws(()=>LocalQualificationSchema.parse(copy),code('INVALID_SCHEMA'));});
 await t.test('recreated-qualification-owner-rejects-unexecuted-record',async()=>{const q=new QualificationRegistry(()=>localQualificationPins(n.f.root));assert.throws(()=>q.assertCurrent(n.profile,n.qualification,n.pins,now()),code('QUALIFICATION_MISMATCH'));});
 for(const key of ['engineDigest','schemaDigest','environmentDigest','dependencyLockDigest','checkDefinitionDigest'] as const)await t.test('restart-incompatible/'+key,async()=>{const a=await n.task(),j=journey(n,{schedule:{usage:'never'}});await j.turn(a);const old=(await n.native.repository.snapshot(a.scope,a.sessionId)).binding,requests=await requestsFor(n,a.binding.runId),pins={...n.pins,[key]:sha(96)},runtime=composeNative({uow:n.f.uow,bindingFor:n.f.bindingFor,pins,profile:n.profile,profiles:n.profiles,adapter:n.f.adapterClient(),descriptors:n.descriptors});await noDispatch(n,()=>assert.rejects(runtime.session.requestTurn(a.scope,{...commandPlaceholder(a),input:'automatic continuation',choice:null})));assert.deepEqual((await n.native.repository.snapshot(a.scope,a.sessionId)).binding,old);assert.deepEqual(await requestsFor(n,a.binding.runId),requests);});
});

test('P13',async t=>{
 const setup=async(intent:'Ask'|'Act'='Act')=>{const a=await n.task({intent,targetEffect:intent==='Act',need:ProfileNeedSchema.parse({...n.need,streamToolArguments:true,outputCap:256})}),j=journey(n,{response:'tool',message:'complete validated ✓'});const result=await j.turn(a,'complete validated ✓');assert.equal(result.status,'completed');const r=j.requests[0]!,c=captured(r).capsule;await proveReceipt(n,r);let effects=0;const validator=new ProposalValidator(n.f.adapterClient(),n.native.compiler,{handoff:async(scope,input)=>{assert.equal(input.target,'local-test-effect');assert.deepEqual(input.arguments,{message:'complete validated ✓'});await j.session.continue(scope,await n.command(a.sessionId),'target',async()=>{effects++;});}});const frames=[];for await(const frame of n.f.adapterClient().stream(r.original)){frames.push(frame);assert.equal(effects,0);}assert.ok(frames.length>1);return {a,j,r,c,validator,frames,effects:()=>effects,input:{request:r,capsule:c,profile:n.profile,descriptors:n.descriptors.get(a.sessionId)!}};};
 const rows=['empty','truncated','sequence','early-final','wrong-kind','malformed','missing-required','unknown-field','unsupported-dialect','forged-output','foreign-original','over-256-chunks'] as const;
 for(const name of rows)await t.test('chunk-arguments/'+name,async()=>{const f=await setup(),first=f.frames[0]!,single=(fragment:string)=>[{...first,fragment,final:true}];let frames:unknown[]=f.frames;
  if(name==='empty')frames=[];else if(name==='truncated')frames=f.frames.slice(0,-1);else if(name==='sequence')frames=[{...first,sequence:2}];else if(name==='early-final')frames=f.frames.map((r,i)=>({...r,final:i===0}));else if(name==='wrong-kind')frames=[{...first,kind:'text',final:true}];else if(name==='malformed')frames=single('{');else if(name==='missing-required')frames=single('{}');else if(name==='unknown-field')frames=single('{"message":"complete validated ✓","grant":"Act"}');else if(name==='unsupported-dialect')frames=[{...first,dialect:'arbitrary'}];else if(name==='forged-output')frames=single('{"message":"forged complete"}');else if(name==='foreign-original')frames=[{...first,original:{...first.original,spaceId:n.f.otherSpace}}];else frames=Array.from({length:257},(_,i)=>({...first,sequence:i+1,fragment:i===0?'{':i===256?'}':' ',final:i===256}));
  const iterable={async *[Symbol.asyncIterator](){for(const frame of frames){assert.equal(f.effects(),0);yield frame;assert.equal(f.effects(),0);}}};await assert.rejects(f.validator.collect(f.a.scope,f.input,iterable));assert.equal(f.effects(),0);
 });
 await t.test('complete-current-Act-proposal-handoff-once-only',async()=>{const f=await setup(),token=await f.validator.collect(f.a.scope,f.input);assert.equal(f.effects(),0);await assert.rejects(f.validator.handoff(f.a.scope,token,'shell'),code('REQUIRED_CAPABILITY_UNSUPPORTED'));assert.equal(f.effects(),0);const result=await Promise.allSettled(Array.from({length:8},()=>f.validator.handoff(f.a.scope,token,'local-test-effect')));assert.equal(result.filter(r=>r.status==='fulfilled').length,1);assert.equal(f.effects(),1);await assert.rejects(f.validator.handoff(f.a.scope,token,'local-test-effect'));assert.equal(f.effects(),1);});
 await t.test('complete-Ask-proposal-remains-no-effect',async()=>{const f=await setup('Ask'),token=await f.validator.collect(f.a.scope,f.input);await assert.rejects(f.validator.handoff(f.a.scope,token,'local-test-effect'),code('INTENT_EXCEEDED'));assert.equal(f.effects(),0);});
});
